map.body:
{
    breaks <- self$get_breaks(limits)
    limits <- self$get_limits()
    all_breaks <- unique0(sort(c(limits[1], breaks, limits[2])))
    if (self$after.stat) {
        x_binned <- cut(x, seq_len(length(all_breaks) + 1) - 0.5, labels = FALSE, include.lowest = TRUE, right = self$right)
        (x - x_binned + 0.5) * diff(all_breaks)[x_binned] + all_breaks[x_binned]
    }
    else {
        x <- as.numeric(self$oob(x, limits))
        x <- ifelse(!is.na(x), x, self$na.value)
        x_binned <- cut(x, all_breaks, labels = FALSE, include.lowest = TRUE, right = self$right)
        x_binned
    }
}

